def run_audit(root, request_path, executable, timeout=1800):
    request = read_json(request_path)
    if request.get('mode') != 'lean' or state(root)['auditRequest'] != request_path.relative_to(root).as_posix():
        raise ProtocolError('not the active lean audit request')
    with file_lock(request_path.with_name('runner.lock')):
        if request_path.with_name('launch.json').exists(): raise ProtocolError('attempt already executed')
        before = compute_workspace_fingerprint(root)
        if not fingerprint_equal(before, request['workspaceFingerprint']): raise ProtocolError('stale audit request')
        skill = Path(__file__).resolve().parents[2] / 'vibe-acceptance-auditor/SKILL.md'
        prompt = (f'Use $vibe-acceptance-auditor at {skill}. Perform the lean independent audit of {root}. '
            f'Read request {request_path} and lean-audit.md. No implementation conversation is available. '
            'Inspect the approved AppSpec and production scenarios independently. Return only the lean audit JSON. '
            'Do not edit source, tests, configuration, AppSpec or work state. Existing receipts are execution evidence, '
            'not proof of assertions; inspect tests and real production wiring. Run missing safe checks. '
            'Known gaps do not block starting the audit; report them. The host writes audit/launch evidence.')
        prior = request.get('previousAudit')
        if prior:
            old = local(root, prior['request'])
            if (sha256_bytes(old.read_bytes()) != prior['requestSha256'] or
                    sha256_bytes(old.with_name('audit.json').read_bytes()) != prior['auditSha256']):
                raise ProtocolError('previous audit changed')
            prompt += (f' This is delta review following {old}. Compare snapshot file hashes, inspect every changed '
                'file and its dependent behavior, recheck all prior findings. Return the complete updated obligation '
                'matrix. If changes are broad or context is unreliable, return BLOCKED requesting a fresh full audit.')
        prompt_path = request_path.with_name('prompt.txt'); prompt_path.write_text(prompt, encoding='utf-8')
        output = request_path.with_name('result.json')
        argv = ([executable, 'exec', 'resume', prior['threadId']] if prior else
            [executable, 'exec', '--sandbox', 'workspace-write', '-C', str(root)])
        argv += ['--json', '--output-last-message', str(output), '-']
        started = utc_now()
        code, stdout, stderr, status = execute_process(argv, input_bytes=prompt.encode('utf-8'), cwd=root, timeout=timeout)
        after = compute_workspace_fingerprint(root)
        if not fingerprint_equal(before, after): status = 'workspace-changed'
        events = request_path.with_name('events.jsonl'); events.write_bytes(stdout)
        request_path.with_name('stderr.log').write_bytes(stderr)
        try:
            ids = [e.get('thread_id') for line in stdout.decode('utf-8').splitlines() if line.strip()
                for e in [json.loads(line)] if e.get('type') == 'thread.started']
        except (ValueError, UnicodeError): ids = []
        launch = {'producer': 'vibe-lean-audit-runner', 'argv': argv, 'threadId': ids[0] if len(ids) == 1 else None,
            'requestSha256': sha256_bytes(request_path.read_bytes()), 'startedAt': started, 'completedAt': utc_now(),
            'exitCode': code, 'executionStatus': status, 'startWorkspaceFingerprint': before, 'workspaceFingerprint': after,
            'eventsSha256': sha256_bytes(stdout), 'promptSha256': sha256_bytes(prompt_path.read_bytes())}
        atomic_write_json(request_path.with_name('launch.json'), launch, refuse_existing=True)
        if code != 0 or status != 'completed' or not launch['threadId']:
            raise ProtocolError('audit failed; preserve attempt and create a new request')
        data = read_json(output)
        atomic_write_json(request_path.with_name('audit.json'), data, refuse_existing=True)
        errors, completion = validate_audit(root, request_path, data)
        if errors: raise ProtocolError('; '.join(errors))
        return completion


def close(root):
    value = state(root)
    if not value.get('auditRequest'): raise ProtocolError('independent audit required')
    request_path = local(root, value['auditRequest'])
    data = read_json(request_path.with_name('audit.json'))
    errors, completion = validate_audit(root, request_path, data)
    if errors or data['verdict'] != 'PASS': raise ProtocolError('; '.join(errors) or 'audit did not PASS')
    manifest = {'mode': 'lean', 'createdAt': utc_now(), **completion,
        'workspaceFingerprint': compute_workspace_fingerprint(root),
        'request': value['auditRequest'], 'requestSha256': sha256_bytes(request_path.read_bytes()),
        'auditSha256': sha256_bytes(request_path.with_name('audit.json').read_bytes()),
        'launchSha256': sha256_bytes(request_path.with_name('launch.json').read_bytes())}
    manifest['receipts'] = {ref: sha256_bytes(local(root, ref).read_bytes())
        for row in data['obligations'] for ref in row.get('receiptRefs', [])}
    atomic_write_json(root / '.vibe/closure.json', manifest)
    return manifest
