/** Deterministic line-framed payload. Authored strings and JSON are UTF-8 hex, so records cannot escape framing. */
class LocalBackupArchiveCodec(private val domainCodec: DomainJsonCodec = DomainJsonCodec()) {
    fun encode(archive: LocalBackupArchive, checkActive: () -> Unit = {}): ByteArray {
        checkActive()
        val snapshot = archive.snapshot
        val lines = buildList {
            add(listOf(MAGIC, archive.formatVersion.toString(), archive.createdAt.toString()).joinToString(SEPARATOR))
            add(encodePreferences(archive.preferences))
            add(encodeManifest(snapshot.manifest))
            snapshot.zones.sortedBy { it.id.value }.forEach { zone ->
                checkActive()
                add(listOf("Z", text(zone.id.value), text(zone.name), zone.type.name, zone.capacity.toString()).joinToString(SEPARATOR))
            }
            snapshot.trayPresets.sortedBy { it.id.value }.forEach { tray ->
                checkActive()
                val shape = when (val value = tray.shape) {
                    is TrayShape.Rectangle -> listOf("RECTANGLE", value.widthCentimetres.toString(), value.lengthCentimetres.toString())
                    is TrayShape.Circle -> listOf("CIRCLE", value.diameterCentimetres.toString(), "")
                }
                add((listOf("T", text(tray.id.value), text(tray.name)) + shape).joinToString(SEPARATOR))
            }
            snapshot.recipes.sortedBy { it.id.value }.forEach {
                checkActive()
                add("R$SEPARATOR${text(domainCodec.encodeRecipe(it))}")
            }
            snapshot.batches.sortedBy { it.id.value }.forEach {
                checkActive()
                add("B$SEPARATOR${text(domainCodec.encodeBatch(it))}")
            }
            snapshot.plans.sortedBy { it.id.value }.forEach {
                checkActive()
                add("L$SEPARATOR${text(domainCodec.encodePlan(it))}")
            }
            snapshot.observations.sortedBy { it.id.value }.forEach {
                checkActive()
                add("O$SEPARATOR${text(domainCodec.encodeObservation(it))}")
            }
            archive.photos.sortedBy { it.id.value }.forEach { photo ->
                checkActive()
                add(listOf("F", text(photo.id.value), photo.sha256, photo.bytes.toHex(checkActive)).joinToString(SEPARATOR))
            }
        }
        checkActive()
        return lines.joinToString("\n", postfix = "\n").encodeToByteArray().also { checkActive() }
    }

    fun decode(bytes: ByteArray, checkActive: () -> Unit = {}): LocalBackupArchive = guardedDecode {
        checkActive()
        val lines = bytes.decodeToString(throwOnInvalidSequence = true).split('\n').filter(String::isNotEmpty)
        val header = fields(lines.firstOrNull() ?: invalid())
        if (header.size != HEADER_FIELD_COUNT || header[RECORD_TYPE_INDEX] != MAGIC) invalid()
        val version = header[1].toIntOrNull() ?: invalid()
        if (version != FORMAT_VERSION) throw LocalDataException(LocalDataErrorKey.ARCHIVE_UNSUPPORTED)
        val createdAt = Instant.parse(header[2])
        val preferences = decodePreferences(lines.getOrNull(1) ?: invalid())
        val manifest = decodeManifest(lines.getOrNull(2) ?: invalid())
        val zones = mutableListOf<GrowZone>()
        val trays = mutableListOf<TraySizePreset>()
        val recipes = mutableListOf<UserGrowRecipe>()
        val batches = mutableListOf<GrowBatch>()
        val plans = mutableListOf<HarvestPlan>()
        val observations = mutableListOf<Observation>()
        val photos = mutableListOf<PrivatePhoto>()
        lines.drop(ARCHIVE_PREAMBLE_LINE_COUNT).forEach { line ->
            checkActive()
            val value = fields(line)
            when (value.firstOrNull()) {
                "Z" -> zones += GrowZone(
                    GrowZoneId(plain(value[1])),
                    plain(value[2]),
                    GrowZoneType.valueOf(value[SHAPE_KIND_INDEX]),
                    value[PRIMARY_VALUE_INDEX].toInt(),
                )
                "T" -> trays += TraySizePreset(
                    TraySizePresetId(plain(value[1])), plain(value[2]),
                    if (value[SHAPE_KIND_INDEX] == "RECTANGLE") {
                        TrayShape.Rectangle(
                            value[PRIMARY_VALUE_INDEX].toDouble(),
                            value[SECONDARY_VALUE_INDEX].toDouble(),
                        )
                    } else if (value[SHAPE_KIND_INDEX] == "CIRCLE") {
                        TrayShape.Circle(value[PRIMARY_VALUE_INDEX].toDouble())
                    } else {
                        invalid()
                    },
                )
                "R" -> recipes += domainCodec.decodeRecipe(plain(value[1]))
                "B" -> batches += domainCodec.decodeBatch(plain(value[1]))
                "L" -> plans += domainCodec.decodePlan(plain(value[1]))
                "O" -> observations += domainCodec.decodeObservation(plain(value[1]))
                "F" -> photos += PrivatePhoto(
                    PhotoId(plain(value[1])),
                    value[PHOTO_BYTES_INDEX].hexToBytes(checkActive),
                    value[2],
                )
                else -> invalid()
            }
        }
        LocalBackupArchive(
            createdAt, ProductSnapshot(manifest, zones, trays, recipes, batches, plans, observations),
            photos, preferences, version,
        )
    }

    private fun encodePreferences(value: ProductPreferences): String {
        val privacy = value.privacyState
        return listOf(
            "P", value.theme.name, value.crashReportingEnabled.toString(), value.notificationsEnabled.toString(),
            privacy?.schemaVersion?.toString().orEmpty(), privacy?.policyVersion?.let(::text).orEmpty(),
            privacy?.expiresAtEpochMillis?.toString().orEmpty(), privacy?.choice?.name.orEmpty(),
            value.summaryTime.toString(), value.soakRemindersEnabled.toString(),
            privacy?.payloadVersion?.toString().orEmpty(), privacy?.endpoint?.let(::text).orEmpty(),
            privacy?.consentRequired?.toString().orEmpty(), privacy?.fetchedAtEpochMillis?.toString().orEmpty(),
        ).joinToString(SEPARATOR)
    }

    private fun decodePreferences(line: String): ProductPreferences {
        val value = fields(line)
        if (value.size !in SUPPORTED_PREFERENCE_FIELD_COUNTS || value[RECORD_TYPE_INDEX] != "P") invalid()
        val privacy = if (value[PRIVACY_SCHEMA_INDEX].isEmpty()) null else AdvertisingPrivacyState(
            schemaVersion = value[PRIVACY_SCHEMA_INDEX].toInt(),
            policyVersion = plain(value[POLICY_VERSION_INDEX]),
            expiresAtEpochMillis = value[EXPIRES_AT_INDEX].toLong(),
            choice = ConsentChoice.valueOf(value[CONSENT_CHOICE_INDEX]),
            payloadVersion = value.getOrNull(PAYLOAD_VERSION_INDEX)?.takeIf(String::isNotEmpty)?.toInt()
                ?: ADVERTISING_PRIVACY_PAYLOAD_VERSION,
            endpoint = value.getOrNull(PRIVACY_ENDPOINT_INDEX)?.takeIf(String::isNotEmpty)?.let(::plain)
                ?: ADVERTISING_PRIVACY_ENDPOINT,
            consentRequired = value.getOrNull(CONSENT_REQUIRED_INDEX)?.takeIf(String::isNotEmpty)?.toBooleanStrict()
                ?: true,
            fetchedAtEpochMillis = value.getOrNull(FETCHED_AT_INDEX)?.takeIf(String::isNotEmpty)?.toLong()
                ?: 0L,
        )
        return ProductPreferences(
            ThemePreference.valueOf(value[1]),
            value[2].toBooleanStrict(),
            value[NOTIFICATIONS_ENABLED_INDEX].toBooleanStrict(),
            privacy,
            summaryTime = SummaryLocalTime.parseOrDefault(value.getOrNull(SUMMARY_TIME_INDEX)),
            soakRemindersEnabled = value.getOrNull(SOAK_REMINDERS_INDEX)?.toBooleanStrictOrNull() ?: true,
        )
    }

    private fun encodeManifest(value: BackupManifest): String {
        val integrity = value.photoIntegrity.entries.sortedBy { it.key.value }
            .joinToString(",") { (id, digest) -> "${text(id.value)}:$digest" }
        return listOf(
            "M", value.schemaVersion.toString(), value.archiveVersion.toString(),
            value.recordCounts["zones"].orZero(), value.recordCounts["trayPresets"].orZero(),
            value.recordCounts["recipes"].orZero(), value.recordCounts["batches"].orZero(),
            value.recordCounts["plans"].orZero(), value.recordCounts["observations"].orZero(), integrity,
        ).joinToString(SEPARATOR)
    }

    private fun decodeManifest(line: String): BackupManifest {
        val value = fields(line)
        if (value.size != MANIFEST_FIELD_COUNT || value[RECORD_TYPE_INDEX] != "M") invalid()
        val counts = linkedMapOf(
            "zones" to value[MANIFEST_ZONES_INDEX].toInt(),
            "trayPresets" to value[MANIFEST_TRAYS_INDEX].toInt(),
            "recipes" to value[MANIFEST_RECIPES_INDEX].toInt(),
            "batches" to value[MANIFEST_BATCHES_INDEX].toInt(),
            "plans" to value[MANIFEST_PLANS_INDEX].toInt(),
            "observations" to value[MANIFEST_OBSERVATIONS_INDEX].toInt(),
        )
        val integrityValue = value[MANIFEST_INTEGRITY_INDEX]
        val integrity = if (integrityValue.isEmpty()) emptyMap() else integrityValue.split(',').associate { entry ->
            val parts = entry.split(':', limit = 2)
            PhotoId(plain(parts[0])) to parts[1]
        }
        return BackupManifest(value[1].toInt(), value[2].toInt(), counts, integrity)
    }

    private fun fields(line: String) = line.split(SEPARATOR)
    private fun text(value: String) = value.encodeToByteArray().toHex()
    private fun plain(value: String) = value.hexToBytes().decodeToString(throwOnInvalidSequence = true)
    factory: SqlDriverFactory,
    private val ioDispatcher: CoroutineDispatcher,
    private val codec: DomainJsonCodec = DomainJsonCodec(),
) : AutoCloseable {
    private val driver = factory.create()
    private val database = SproutPaceDatabase(driver)
    private val queries = database.sproutPaceQueries

    val watchZones: () -> Flow<List<GrowZone>> = { queries.selectZones(::mapZone).listFlow() }
    val watchTrayPresets: () -> Flow<List<TraySizePreset>> = { queries.selectTrayPresets(::mapTray).listFlow() }
    val watchRecipes: () -> Flow<List<UserGrowRecipe>> = { queries.selectRecipes().decodedListFlow(codec::decodeRecipe) }
    val watchBatches: () -> Flow<List<GrowBatch>> = { queries.selectBatches().decodedListFlow(codec::decodeBatch) }
    val watchPlans: () -> Flow<List<HarvestPlan>> = { queries.selectPlans().decodedListFlow(codec::decodePlan) }
    val watchObservations: () -> Flow<List<Observation>> = {
        queries.selectObservations().decodedListFlow(codec::decodeObservation)
    }

    suspend fun snapshot(): ProductSnapshot = withContext(ioDispatcher) { snapshotNow() }

    /** Startup-only check used before the root component is created. */
    fun hasMinimumGrowingSetup(): Boolean = snapshotNow().let { snapshot ->
        snapshot.zones.isNotEmpty() && snapshot.trayPresets.isNotEmpty() && snapshot.plans.isNotEmpty()
    }

    suspend fun saveZone(zone: GrowZone): GrowZone = write {
        val order = snapshotNow().zones.indexOfFirst { it.id == zone.id }.takeIf { it >= 0 }
            ?: snapshotNow().zones.size
        queries.upsertZone(zone.id.value, zone.name, zone.type.name, zone.capacity.toLong(), order.toLong())
        zone
    }

    suspend fun saveTrayPreset(preset: TraySizePreset): TraySizePreset = write {
        val (kind, primary, secondary) = when (val shape = preset.shape) {
            is TrayShape.Rectangle -> Triple("RECTANGLE", shape.widthCentimetres, shape.lengthCentimetres)
            is TrayShape.Circle -> Triple("CIRCLE", shape.diameterCentimetres, null)
        }
        val order = snapshotNow().trayPresets.indexOfFirst { it.id == preset.id }.takeIf { it >= 0 }
            ?: snapshotNow().trayPresets.size
        queries.upsertTrayPreset(preset.id.value, preset.name, kind, primary, secondary, order.toLong())
        preset
    }

    suspend fun saveRecipe(recipe: UserGrowRecipe): UserGrowRecipe = write {
        val order = snapshotNow().recipes.indexOfFirst { it.id == recipe.id }.takeIf { it >= 0 }
            ?: snapshotNow().recipes.size
        queries.upsertRecipe(recipe.id.value, recipe.name, recipe.cultureId?.value, codec.encodeRecipe(recipe), order.toLong())
        recipe
    }

    suspend fun saveBatch(batch: GrowBatch): GrowBatch = write {
        val snapshot = snapshotNow()
        val assigned = batch.placement as? Placement.Assigned
        val resolved = if (!batch.state.isTerminal && assigned != null &&
            snapshot.zones.none { it.id == assigned.zoneId }) {
            batch.copy(placement = Placement.Unassigned(assigned.zoneNameSnapshot))
        } else batch
        val order = snapshot.batches.indexOfFirst { it.id == batch.id }.takeIf { it >= 0 } ?: snapshot.batches.size
        saveBatchNow(resolved, order)
        resolved
    }

    private fun saveBatchNow(batch: GrowBatch, order: Int) {
        queries.upsertBatch(
            batch.id.value, batch.state.name, batch.recipe.sourceRecipeId?.value,
            batch.recipe.builtInCultureId?.value, codec.encodeBatch(batch), order.toLong(),
        )
    }

    suspend fun savePlan(plan: HarvestPlan): HarvestPlan = write {
        val order = snapshotNow().plans.indexOfFirst { it.id == plan.id }.takeIf { it >= 0 }
            ?: snapshotNow().plans.size
        queries.upsertPlan(plan.id.value, codec.encodePlan(plan), order.toLong())
        plan
    }

    suspend fun saveObservation(observation: Observation): Observation = write {
        queries.upsertObservation(
            observation.id.value, observation.batchId.value, observation.occurredAt.toString(),
            observation.photoId?.value, codec.encodeObservation(observation),
        )
        observation
    }

    val deleteZone: suspend (GrowZoneId) -> Unit = { id ->
        write {
            snapshotNow().batches.forEachIndexed { index, batch ->
                val assigned = batch.placement as? Placement.Assigned
                if (!batch.state.isTerminal && assigned?.zoneId == id) {
                    saveBatchNow(batch.copy(placement = Placement.Unassigned(assigned.zoneNameSnapshot)), index)
                }
            }
            queries.deleteZone(id.value)
        }
    }
    val deleteTrayPreset: suspend (TraySizePresetId) -> Unit = { id -> write { queries.deleteTrayPreset(id.value) } }
    val deleteRecipe: suspend (RecipeId) -> Unit = { id -> write { queries.deleteRecipe(id.value) } }
    val deletePlan: suspend (HarvestPlanId) -> Unit = { id -> write { queries.deletePlan(id.value) } }
    val deleteObservation: suspend (ObservationId) -> Unit = { id -> write { queries.deleteObservation(id.value) } }
    val deleteBatch: suspend (BatchId) -> Unit = { id -> write { queries.deleteBatch(id.value) } }

    suspend fun replace(snapshot: ProductSnapshot) = write { replaceNow(snapshot) }
    suspend fun erase() = write { clearNow() }

    internal fun <T> transaction(block: () -> T): T = database.transactionWithResult { block() }
    internal fun replaceNow(snapshot: ProductSnapshot) {
        clearNow()
        snapshot.zones.forEachIndexed { index, zone ->
            queries.upsertZone(zone.id.value, zone.name, zone.type.name, zone.capacity.toLong(), index.toLong())
        }
        snapshot.trayPresets.forEachIndexed { index, preset ->
            val values = when (val shape = preset.shape) {
                is TrayShape.Rectangle -> Triple("RECTANGLE", shape.widthCentimetres, shape.lengthCentimetres)
                is TrayShape.Circle -> Triple("CIRCLE", shape.diameterCentimetres, null)
            }
            queries.upsertTrayPreset(preset.id.value, preset.name, values.first, values.second, values.third, index.toLong())
        }
        snapshot.recipes.forEachIndexed { index, recipe ->
            queries.upsertRecipe(recipe.id.value, recipe.name, recipe.cultureId?.value, codec.encodeRecipe(recipe), index.toLong())
        }
        snapshot.batches.forEachIndexed { index, batch ->
            queries.upsertBatch(batch.id.value, batch.state.name, batch.recipe.sourceRecipeId?.value,
                batch.recipe.builtInCultureId?.value, codec.encodeBatch(batch), index.toLong())
        }
        snapshot.plans.forEachIndexed { index, plan ->
            queries.upsertPlan(plan.id.value, codec.encodePlan(plan), index.toLong())
        }
        snapshot.observations.forEach { observation ->
            queries.upsertObservation(observation.id.value, observation.batchId.value, observation.occurredAt.toString(),
                observation.photoId?.value, codec.encodeObservation(observation))
        }
    }

    internal fun snapshotNow(): ProductSnapshot {
        val zones = queries.selectZones(::mapZone).executeAsList()
        val trays = queries.selectTrayPresets(::mapTray).executeAsList()
        val recipes = queries.selectRecipes().executeAsList().map(codec::decodeRecipe)
        val batches = queries.selectBatches().executeAsList().map(codec::decodeBatch)
        val plans = queries.selectPlans().executeAsList().map(codec::decodePlan)
        val observations = queries.selectObservations().executeAsList().map(codec::decodeObservation)
        return ProductSnapshot(
            manifest = SnapshotValidation.manifest(zones, trays, recipes, batches, plans, observations, emptyMap()),
            zones = zones, trayPresets = trays, recipes = recipes, batches = batches,
            plans = plans, observations = observations,
        )
    }

    internal fun clearNow() {
        queries.deleteAllObservations()
        queries.deleteAllPlans()
        queries.deleteAllBatches()
        queries.deleteAllRecipes()
        queries.deleteAllTrayPresets()
        queries.deleteAllZones()
    }

    private suspend fun <T> write(block: () -> T): T = withContext(ioDispatcher) { transaction(block) }
    private fun <T : Any> Query<T>.listFlow(): Flow<List<T>> = asFlow().mapToList(ioDispatcher)
    private fun <T : Any> Query<String>.decodedListFlow(decode: (String) -> T): Flow<List<T>> =
        asFlow()
            .mapToList(ioDispatcher)
            .map { payloads -> payloads.map(decode) }

